export const COPILOT_HTML = "<!doctype html>\n<html lang=\"en\"><head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#08090c\"><meta name=\"description\" content=\"Live visual guidance.\">\n<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'none'; form-action 'self'; connect-src 'self' wss:; img-src 'self' data: blob:; style-src 'self'; script-src 'self'; media-src 'self' blob:\">\n<title>Vision 0.4.0</title><link rel=\"stylesheet\" href=\"/copilot.css?v=0.4.36\"><script src=\"/transcript-merge.js\" defer></script><script src=\"/copilot.js?v=0.4.54\" defer></script><script src=\"/session-ui.js\" defer></script></head>\n<body><main class=\"camera-app\" aria-label=\"Camera conversation\"><section class=\"camera-stage pre-start initial-intro\" id=\"cameraStage\" aria-label=\"Live camera view\">\n<video id=\"videoPreview\" autoplay playsinline muted aria-label=\"Live camera preview\"></video>\n\n<button type=\"button\" id=\"showProblemButton\" class=\"show-problem-button\" aria-label=\"Slide to show your problem, or press Enter to start\" title=\"Slide to show your problem\"><span class=\"vision-slide-track\" aria-hidden=\"true\"><span class=\"vision-slide-progress\"></span><span class=\"vision-slide-copy\"><span class=\"vision-slide-label\" id=\"visionSlideLabel\">Slide to show your problem</span></span><span class=\"vision-slide-handle\" id=\"visionSlideHandle\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"7.2\"/><circle cx=\"12\" cy=\"12\" r=\"3.1\"/><path d=\"M12 2.8v2M12 19.2v2M2.8 12h2M19.2 12h2\"/></svg></span></span><span class=\"sr-only\">SHOW ME YOUR PROBLEM</span></button>\n<div class=\"camera-placeholder\" id=\"cameraPlaceholder\"><strong class=\"sr-only\">Ready</strong><span class=\"sr-only\">Start the camera and conversation using the call control.</span></div><div class=\"voice-glow\" aria-hidden=\"true\"><span></span><span></span><span></span></div><div class=\"edge-glow\" aria-hidden=\"true\"></div>\n<div class=\"connection-notice\" id=\"connectionNotice\" hidden role=\"status\" aria-live=\"polite\" aria-labelledby=\"connectionNoticeTitle\" aria-describedby=\"connectionNoticeMessage\">\n  <div class=\"connection-notice-symbol\" aria-hidden=\"true\"></div>\n  <div class=\"connection-notice-copy\">\n    <strong id=\"connectionNoticeTitle\">Connecting securely</strong>\n    <p id=\"connectionNoticeMessage\">Just a moment</p>\n  </div>\n  <div class=\"connection-notice-progress\" id=\"connectionNoticeProgress\" aria-hidden=\"true\"><span></span></div>\n  <button type=\"button\" class=\"connection-notice-action\" id=\"connectionNoticeAction\" hidden>Try again</button>\n</div>\n<header class=\"floating-top\"><button type=\"button\" id=\"backButton\" class=\"back-control\" aria-label=\"Go back\" title=\"Back\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m14.5 5.5-6.5 6.5 6.5 6.5\"/></svg></button><div class=\"top-actions\"><button type=\"button\" id=\"openLibrary\" class=\"library-open-control\" aria-label=\"History and Key Memories\" title=\"History and Key Memories\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M3.5 12a8.5 8.5 0 1 0 2.49-6.01L3.5 8.5\"/><path d=\"M3.5 3.5v5h5\"/><path d=\"M12 7v5l3.2 1.9\"/></svg></button><button type=\"button\" class=\"logout-control\" data-logout aria-label=\"Sign out\" title=\"Sign out\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M10 17l5-5-5-5M15 12H3\"/><path d=\"M12 3h6a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-6\"/></svg></button></div></header>\n<section id=\"librarySheet\" class=\"library-sheet\" hidden aria-hidden=\"true\">\n  <button type=\"button\" class=\"library-scrim\" id=\"libraryScrim\" aria-label=\"Close Library\"></button>\n  <div class=\"library-panel\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"libraryTitle\">\n    <header class=\"library-header\">\n      <div><p class=\"library-eyebrow\">YOUR SPACE</p><h2 id=\"libraryTitle\">History &amp; Key Memories</h2><p class=\"library-subtitle\">Pick up where you left off.</p></div>\n      <button type=\"button\" id=\"closeLibrary\" class=\"library-close\" aria-label=\"Close Library\">×</button>\n    </header>\n    <nav class=\"library-tabs\" aria-label=\"Your library\">\n      <button type=\"button\" class=\"library-tab is-selected\" data-library-tab=\"history\" aria-selected=\"true\">History</button>\n      <button type=\"button\" class=\"library-tab\" data-library-tab=\"memories\" aria-selected=\"false\">Key Memories</button>\n    </nav>\n    <p id=\"libraryStatus\" class=\"library-status\" role=\"status\" aria-live=\"polite\"></p>\n    <section id=\"libraryHistoryView\" class=\"library-view\" aria-label=\"Past conversations\">\n      <label class=\"library-search\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"10.8\" cy=\"10.8\" r=\"6.8\"/><path d=\"m16 16 4.5 4.5\"/></svg><input id=\"conversationSearch\" type=\"search\" autocomplete=\"off\" placeholder=\"Search your conversations\" aria-label=\"Search your conversations\"></label>\n      <div id=\"conversationList\" class=\"library-list\"></div>\n    </section>\n    <section id=\"conversationDetailView\" class=\"library-view\" hidden aria-label=\"Conversation details\">\n      <button type=\"button\" id=\"conversationDetailBack\" class=\"library-back\">‹ <span>All conversations</span></button>\n      <h3 id=\"detailTitle\" class=\"library-detail-title\">Conversation</h3>\n      <p id=\"detailMeta\" class=\"library-detail-meta\"></p>\n      <div id=\"detailSummary\" class=\"library-summary\" hidden></div>\n      <div id=\"detailTask\" class=\"library-task\" hidden></div>\n      <div id=\"detailTranscript\" class=\"detail-transcript\" aria-label=\"Saved transcript\"></div>\n      <div class=\"library-detail-footer\"><button type=\"button\" id=\"continueConversation\" class=\"library-primary\">Continue with Moina <span aria-hidden=\"true\">↗</span></button></div>\n    </section>\n    <section id=\"libraryMemoryView\" class=\"library-view\" hidden aria-label=\"Key Memories and preferences\">\n      <div class=\"memory-setting-row\">\n        <div class=\"memory-setting-copy\"><h3>Learn my preferences</h3><p>Remember preferences you state directly and use them in future conversations.</p></div>\n        <label class=\"apple-switch\"><input id=\"memoryEnabledSwitch\" type=\"checkbox\" checked aria-label=\"Turn preference memory on or off\"><span aria-hidden=\"true\"></span></label>\n      </div>\n      <p class=\"memory-privacy-note\">AskMoina saves reusable preferences you explicitly express, like your preferred language or answer style. It does not intentionally save sensitive personal disclosures or credentials. You can edit or delete memories any time.</p>\n      <form id=\"memoryAddForm\" class=\"memory-add-form\">\n        <label for=\"memoryInput\" class=\"sr-only\">Add a memory</label>\n        <input id=\"memoryInput\" type=\"text\" maxlength=\"240\" autocomplete=\"off\" placeholder=\"Add a preference…\" required>\n        <button type=\"submit\" aria-label=\"Save memory\">Add</button>\n      </form>\n      <div class=\"memory-list-heading\"><h3>Saved for you</h3><button type=\"button\" id=\"clearAllMemories\" class=\"library-text-action\">Clear all</button></div>\n      <div id=\"memoryList\" class=\"memory-list\"></div>\n    </section>\n  </div>\n</section>\n<div class=\"camera-top-badge sr-only\" id=\"frameBadge\"><span class=\"live-dot\"></span> WAITING FOR CAMERA</div><span class=\"camera-state sr-only\" id=\"cameraState\"><span class=\"state-dot\"></span> Camera paused</span>\n<div class=\"focus-marker\" id=\"focusMarker\" data-region=\"center\" hidden><div class=\"focus-brackets\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i></div><div class=\"focus-card\"><span class=\"focus-eyebrow\">MOINA'S FOCUS</span><strong id=\"focusLabel\">Target</strong><span class=\"focus-hint\" id=\"focusHint\"></span><p id=\"focusInstruction\"></p></div><button type=\"button\" id=\"clearMarker\" class=\"clear-marker\" aria-label=\"Clear focus marker\">×</button></div>\n<div class=\"approx-tag sr-only\" id=\"approxTag\" hidden>Approximate focus · not world-locked AR</div>\n<div class=\"zoom-dock\" id=\"zoomDock\" hidden aria-hidden=\"true\" aria-label=\"Camera zoom controls\"><button type=\"button\" id=\"zoomOut\" aria-label=\"Zoom out\" disabled>−</button><label class=\"sr-only\" for=\"zoomSlider\">Camera zoom</label><input id=\"zoomSlider\" type=\"range\" min=\"1\" max=\"3\" step=\"0.1\" value=\"1\" aria-label=\"Camera zoom\" disabled><output id=\"zoomLabel\" for=\"zoomSlider\">1×</output><button type=\"button\" id=\"zoomIn\" aria-label=\"Zoom in\" disabled>+</button></div>\n<section class=\"live-search-status\" id=\"liveSearchStatus\" hidden aria-labelledby=\"liveSearchTitle\" aria-describedby=\"liveSearchMessage\">\n  <div class=\"live-search-status-top\">\n    <span class=\"live-search-mark\" aria-hidden=\"true\"><span></span></span>\n    <div class=\"live-search-copy\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">\n      <p class=\"live-search-title\" id=\"liveSearchTitle\">Searching the web</p>\n      <p class=\"live-search-message\" id=\"liveSearchMessage\">Checking current sources</p>\n    </div>\n    <output class=\"live-search-percent\" id=\"liveSearchPercent\" for=\"liveSearchProgress\">0%</output>\n  </div>\n  <div class=\"live-search-track\" id=\"liveSearchProgress\" role=\"progressbar\" aria-label=\"Estimated search progress\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"0\"><span id=\"liveSearchProgressBar\"></span></div>\n</section>\n<section id=\"responseCardTray\" class=\"response-card-tray\" hidden role=\"region\" aria-label=\"Moina response card\" aria-labelledby=\"responseCardTitle\">\n  <header class=\"response-card-header\">\n    <div class=\"response-card-heading\">\n      <span class=\"response-card-eyebrow\" id=\"responseCardType\">REFERENCE</span>\n      <h2 id=\"responseCardTitle\">Reference</h2>\n    </div>\n    <div class=\"response-card-actions\">\n      <button type=\"button\" id=\"responseCardMinimize\" aria-label=\"Minimize answer sheet to camera\" title=\"Back to camera\">↓</button>\n      <button type=\"button\" id=\"responseCardCollapse\" aria-expanded=\"true\" aria-controls=\"responseCardDetails\" aria-label=\"Collapse card details\" title=\"Collapse card\">−</button>\n      <button type=\"button\" id=\"responseCardDismiss\" aria-label=\"Dismiss response card\" title=\"Dismiss card\">×</button>\n    </div>\n  </header>\n  <div id=\"responseCardDetails\" class=\"response-card-details\">\n    <p id=\"responseCardSummary\" class=\"response-card-summary\" hidden></p>\n    <div id=\"responseCardContent\" class=\"response-card-content\"></div>\n  </div>\n  <div id=\"responseCardStatus\" class=\"response-card-status\" role=\"status\" aria-live=\"polite\">Keep this reference visible while you work.</div>\n</section>\n<button type=\"button\" id=\"responseCardRestore\" class=\"response-card-restore\" hidden aria-label=\"Reopen answer sheet\">↑ <span>Show answer</span></button>\n<section class=\"live-search-status\" id=\"liveSearchStatus\" hidden aria-labelledby=\"liveSearchTitle\" aria-describedby=\"liveSearchMessage\">\n  <div class=\"live-search-status-top\">\n    <span class=\"live-search-mark\" aria-hidden=\"true\"><span></span></span>\n    <div class=\"live-search-copy\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">\n      <p class=\"live-search-title\" id=\"liveSearchTitle\">Searching the web</p>\n      <p class=\"live-search-message\" id=\"liveSearchMessage\">Checking current sources</p>\n    </div>\n    <output class=\"live-search-percent\" id=\"liveSearchPercent\" for=\"liveSearchProgress\">0%</output>\n  </div>\n  <div class=\"live-search-track\" id=\"liveSearchProgress\" role=\"progressbar\" aria-label=\"Estimated search progress\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"0\"><span id=\"liveSearchProgressBar\"></span></div>\n</section>\n<section class=\"caption-dock\" hidden aria-label=\"Conversation captions\"><div class=\"status-line sr-only\"><span class=\"assistant-orb\" aria-hidden=\"true\"></span><div class=\"status-copy\"><strong id=\"connectionPill\" data-state=\"ready\">READY</strong><p id=\"status\" role=\"status\" aria-live=\"polite\"> </p></div><span id=\"availability\" class=\"availability\" role=\"status\" aria-live=\"polite\"> </span></div><div class=\"transcript\" id=\"transcript\" role=\"log\" aria-live=\"polite\" aria-relevant=\"additions text\"><div class=\"empty-state sr-only\" id=\"emptyTranscript\"></div></div><button type=\"button\" id=\"clearTranscript\" class=\"clear-captions\" aria-label=\"Clear captions\" title=\"Clear captions\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M10 11v7M14 11v7M6 7l1 14h10l1-14M9 7V4h6v3\"/></svg></button></section>\n<button type=\"button\" id=\"spatialArButton\" class=\"control-icon spatial-ar-button\" hidden disabled title=\"Spatial guide\" aria-label=\"Spatial guide\" aria-hidden=\"true\" tabindex=\"-1\"></button>\n<nav class=\"camera-controls\" aria-label=\"Call controls\"><div class=\"primary-control-row\">\n<button type=\"button\" id=\"muteMic\" class=\"control-icon\" disabled aria-label=\"Mute microphone\" title=\"Mute microphone\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"9\" y=\"3\" width=\"6\" height=\"11\" rx=\"3\"/><path d=\"M5 11a7 7 0 0 0 14 0M12 18v3M8 21h8\"/></svg><span class=\"sr-only\">Mute microphone</span></button>\n<button type=\"button\" id=\"flipCamera\" class=\"control-icon\" disabled aria-label=\"Switch camera\" title=\"Switch camera\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"8\" y=\"8.5\" width=\"8\" height=\"7\" rx=\"1.5\"/><circle cx=\"12\" cy=\"12\" r=\"2.1\"/><path d=\"M5.2 8.2A8.6 8.6 0 0 1 18 6l1.5 1.5M19.5 4.2v3.4h-3.4\"/><path d=\"M18.8 15.8A8.6 8.6 0 0 1 6 18l-1.5-1.5M4.5 19.8v-3.4h3.4\"/></svg></button>\n<button type=\"button\" id=\"toggleCopilot\" class=\"control-icon stop-button\" disabled aria-pressed=\"false\" aria-label=\"Start call\" title=\"Start call\"><svg class=\"icon-start\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"3.2\" y=\"6.6\" width=\"11.5\" height=\"10.8\" rx=\"2.2\"/><path d=\"m14.7 10 6.1-3.1v10.2l-6.1-3.1\"/></svg><svg class=\"icon-end\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4.7 8.5 3.5 6.8a1.5 1.5 0 0 1 .2-2l1.4-1.3a1.6 1.6 0 0 1 2-.1l3 2.1a1.6 1.6 0 0 1 .6 1.8l-.8 2.2a13.5 13.5 0 0 0 6.6 6.6l2.2-.8a1.6 1.6 0 0 1 1.8.6l2.1 3a1.6 1.6 0 0 1-.1 2l-1.3 1.4a1.5 1.5 0 0 1-2 .2l-1.7-1.2C10.2 17.8 6.2 13.8 4.7 8.5Z\"/></svg><span id=\"buttonLabel\" class=\"sr-only\">Checking voice</span></button>\n</div></nav>\n<div class=\"spatial-hud spatial-hud-jarvis\" id=\"spatialHud\" hidden aria-label=\"Moina visual guide\">\n  <section class=\"spatial-card\">\n    <header class=\"spatial-topbar\">\n      <div class=\"spatial-brand\"><span class=\"spatial-live-dot\" aria-hidden=\"true\"></span></div>\n      <button type=\"button\" id=\"exitSpatialAr\" class=\"spatial-close\" aria-label=\"Done and return to Co-Pilot\">×</button>\n    </header>\n\n    <div class=\"spatial-focus-stack\">\n      <p id=\"spatialStatus\" role=\"status\" aria-live=\"polite\">Scanning for a surface…</p>\n      <div class=\"spatial-guidance\" id=\"spatialGuidance\" aria-label=\"Current visual instruction\">\n        <span class=\"spatial-guidance-eyebrow\">CURRENT TARGET</span>\n        <strong id=\"spatialTargetLabel\">Ready when you are</strong>\n        <p id=\"spatialTargetInstruction\">Ask Moina what you want to find, then follow the highlighted cue.</p>\n        <small id=\"spatialTargetHint\">Move your phone slowly until the ring sits on the surface you want.</small>\n      </div>\n    </div>\n\n    <div class=\"spatial-bottom-stack\">\n      <div class=\"spatial-step-panel\" id=\"spatialStepPanel\" aria-label=\"Guidance progress\">\n        <div class=\"spatial-step-header\">\n          <strong>YOUR GUIDE</strong>\n          <span id=\"spatialStepProgress\" role=\"status\" aria-live=\"polite\">Ready</span>\n        </div>\n        <div class=\"spatial-progress-track\" id=\"spatialProgressTrack\" hidden role=\"progressbar\" aria-label=\"Walkthrough progress\" aria-valuemin=\"0\" aria-valuemax=\"1\" aria-valuenow=\"0\"></div>\n        <p id=\"spatialStepMessage\">Move the phone until the ring rests on the target. Then tap Place cue.</p>\n        <div class=\"spatial-step-actions\" aria-hidden=\"true\">\n          <button type=\"button\" id=\"spatialStepPrevious\" disabled>Back</button>\n          <button type=\"button\" id=\"spatialStepConfirm\" disabled>Confirm step</button>\n          <button type=\"button\" id=\"spatialStepNext\" disabled>Next</button>\n          <button type=\"button\" id=\"spatialStepFinish\" disabled>Done</button>\n        </div>\n        <small class=\"spatial-step-footnote\">Follow the ring. Moina will show you one step at a time.</small>\n      </div>\n\n      <div class=\"spatial-action-panel\">\n        <span class=\"spatial-action-eyebrow\" id=\"spatialActionEyebrow\">SCANNING FOR A SURFACE</span>\n        <div class=\"spatial-actions\">\n          <button type=\"button\" id=\"placeSpatialAnchor\" disabled>Finding surface…</button>\n        </div>\n        <p id=\"spatialActionHint\" role=\"status\" aria-live=\"polite\">Move your phone slowly. When the ring appears over a surface, Moina will let you place the cue.</p>\n      </div>\n\n      <details class=\"spatial-advanced\" id=\"spatialAdvanced\">\n        <summary>More options</summary>\n        <div class=\"spatial-advanced-content\">\n          <div class=\"spatial-scene-panel\" aria-label=\"Saved spatial scene\">\n            <div class=\"spatial-scene-header\">\n              <strong>SAVED GUIDE</strong>\n              <span id=\"spatialSceneCount\" role=\"status\" aria-live=\"polite\">0 pinned cues</span>\n            </div>\n            <label class=\"spatial-scene-label\" for=\"spatialSceneName\">Save these cues as</label>\n            <input id=\"spatialSceneName\" maxlength=\"60\" autocomplete=\"off\" placeholder=\"e.g. My study desk\" />\n            <div class=\"spatial-scene-actions\">\n              <button type=\"button\" id=\"spatialScenePin\" disabled>Pin current cue</button>\n              <button type=\"button\" id=\"spatialSceneSave\" disabled>Save guide</button>\n            </div>\n            <div class=\"spatial-scene-actions\">\n              <select id=\"spatialSceneSelect\" aria-label=\"Choose a saved guide\">\n                <option value=\"\">No saved guides yet</option>\n              </select>\n              <button type=\"button\" id=\"spatialSceneLoad\" disabled>Load</button>\n              <button type=\"button\" id=\"spatialSceneClear\" disabled>Clear pins</button>\n            </div>\n            <small>Saved guides keep instructions on this device. You'll line the cues up again next time.</small>\n          </div>\n          <div class=\"spatial-aim-panel\" aria-label=\"Fine tune target alignment\">\n            <strong>FINE-TUNE TARGET</strong>\n            <p id=\"spatialAimLabel\" role=\"status\" aria-live=\"polite\">Waiting for a target…</p>\n            <div class=\"spatial-aim-controls\">\n              <button type=\"button\" id=\"spatialAimLeft\" aria-label=\"Nudge target left\" disabled>←</button>\n              <button type=\"button\" id=\"spatialAimUp\" aria-label=\"Nudge target up\" disabled>↑</button>\n              <button type=\"button\" id=\"spatialAimReset\" disabled>Reset</button>\n              <button type=\"button\" id=\"spatialAimDown\" aria-label=\"Nudge target down\" disabled>↓</button>\n              <button type=\"button\" id=\"spatialAimRight\" aria-label=\"Nudge target right\" disabled>→</button>\n            </div>\n            <small>Moina's target is an estimate. Check the ring before placing a cue.</small>\n          </div>\n          <div class=\"spatial-advanced-actions\">\n            <button type=\"button\" id=\"clearSpatialAnchor\" disabled>Clear current cue</button>\n          </div>\n          <p class=\"spatial-note\">After confirmation, the 3D cue card is anchored at the selected hit-test point. This uses screen-region guidance plus your visual confirmation; it does not recognize object geometry or guarantee the chosen surface is the named object. When Co-Pilot is already connected, voice stays live in Spatial AR while camera frames pause; live visual updates resume after you exit AR. If voice setup is incomplete, it may need to end before AR starts.</p>\n        </div>\n      </details>\n      <p class=\"spatial-note spatial-note-short\">The ring is a guide, not object recognition. Check placement before continuing.</p>\n    </div>\n  </section>\n</div>\n<p class=\"privacy-hint\">A camera preview is shown in Vision. Live mic audio and selected camera frames are processed by Google Cloud Vertex AI. To support reconnection, Google may temporarily cache session content for up to 24 hours. AskMoina does not save raw recordings by default.</p></section></main></body></html>";
